import React, { useState, useEffect } from 'react';
import { Container, Row, Col, Card, Button, Form, Spinner, Alert, Pagination } from 'react-bootstrap';
import { Link, useSearchParams } from 'react-router-dom';
import { postsAPI } from '../../services/api';

const PostsList = () => {
  const [posts, setPosts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [pagination, setPagination] = useState({});
  const [searchParams, setSearchParams] = useSearchParams();

  const search = searchParams.get('search') || '';
  const page = parseInt(searchParams.get('page')) || 1;

  useEffect(() => {
    fetchPosts();
  }, [search, page]);

  const fetchPosts = async () => {
    try {
      setLoading(true);
      const params = { page, per_page: 9 };
      if (search) params.search = search;

      const response = await postsAPI.getAll(params);
      setPosts(response.data.data);
      setPagination({
        currentPage: response.data.current_page,
        lastPage: response.data.last_page,
        total: response.data.total,
      });
    } catch (err) {
      setError('Failed to load posts');
      console.error('Error fetching posts:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleSearch = (e) => {
    e.preventDefault();
    const formData = new FormData(e.target);
    const searchValue = formData.get('search');

    setSearchParams(prev => {
      const newParams = new URLSearchParams(prev);
      if (searchValue) {
        newParams.set('search', searchValue);
      } else {
        newParams.delete('search');
      }
      newParams.delete('page'); // Reset to first page
      return newParams;
    });
  };

  const handlePageChange = (newPage) => {
    setSearchParams(prev => {
      const newParams = new URLSearchParams(prev);
      newParams.set('page', newPage.toString());
      return newParams;
    });
  };

  if (loading) {
    return (
      <Container className="text-center py-5">
        <Spinner animation="border" role="status">
          <span className="visually-hidden">Loading...</span>
        </Spinner>
      </Container>
    );
  }

  return (
    <Container className="py-5">
      <Row>
        <Col>
          <h1 className="mb-4">Travel Posts</h1>

          {/* Search Form */}
          <Form onSubmit={handleSearch} className="mb-4">
            <Row>
              <Col md={8}>
                <Form.Control
                  type="text"
                  name="search"
                  placeholder="Search posts..."
                  defaultValue={search}
                />
              </Col>
              <Col md={4}>
                <Button type="submit" variant="primary" className="w-100">
                  Search
                </Button>
              </Col>
            </Row>
          </Form>

          {error && <Alert variant="danger">{error}</Alert>}

          {/* Posts Grid */}
          <Row>
            {posts.map(post => (
              <Col md={4} key={post.id} className="mb-4">
                <Card className="h-100">
                  {post.image && (
                    <Card.Img 
                      variant="top" 
                      src={`http://127.0.0.1:8000/storage/${post.image}`}
                      style={{ height: '200px', objectFit: 'cover' }}
                    />
                  )}
                  <Card.Body className="d-flex flex-column">
                    <Card.Title>{post.title}</Card.Title>
                    <Card.Text className="flex-grow-1">
                      {post.content.replace(/<[^>]*>/g, '').substring(0, 150)}...
                    </Card.Text>
                    <div className="mt-auto">
                      <small className="text-muted">
                        By {post.creator?.name} • {new Date(post.created_at).toLocaleDateString()}
                      </small>
                      <div className="mt-2">
                        <Button as={Link} to={`/posts/${post.id}`} variant="primary" size="sm">
                          Read More
                        </Button>
                      </div>
                    </div>
                  </Card.Body>
                </Card>
              </Col>
            ))}
          </Row>

          {posts.length === 0 && !loading && (
            <div className="text-center py-5">
              <h4>No posts found</h4>
              <p className="text-muted">Try adjusting your search criteria.</p>
            </div>
          )}

          {/* Pagination */}
          {pagination.lastPage > 1 && (
            <Row>
              <Col className="d-flex justify-content-center">
                <Pagination>
                  <Pagination.Prev 
                    disabled={pagination.currentPage === 1}
                    onClick={() => handlePageChange(pagination.currentPage - 1)}
                  />

                  {[...Array(pagination.lastPage)].map((_, index) => {
                    const pageNum = index + 1;
                    return (
                      <Pagination.Item
                        key={pageNum}
                        active={pageNum === pagination.currentPage}
                        onClick={() => handlePageChange(pageNum)}
                      >
                        {pageNum}
                      </Pagination.Item>
                    );
                  })}

                  <Pagination.Next 
                    disabled={pagination.currentPage === pagination.lastPage}
                    onClick={() => handlePageChange(pagination.currentPage + 1)}
                  />
                </Pagination>
              </Col>
            </Row>
          )}
        </Col>
      </Row>
    </Container>
  );
};

export default PostsList;
